package com.formation.book.controller;
import com.formation.book.exception.*; import com.formation.book.service.BookService; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest; import org.springframework.boot.test.mock.mockito.MockBean; import org.springframework.test.web.servlet.MockMvc; import static org.mockito.Mockito.*; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.patch; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
@WebMvcTest(BookController.class) class BookControllerTest { @Autowired MockMvc mvc; @MockBean BookService service; @Test void exhaustedStockIs409() throws Exception {when(service.decrement(1L)).thenThrow(new StockConflictException("Aucun exemplaire disponible pour ce livre"));mvc.perform(patch("/api/books/1/decrement-stock")).andExpect(status().isConflict());} }
